#' The variant-effect map, in words and as a picture
#'
#' Shows a run's variant-effect map with the given settings and returns the map described in
#' words, with the number of cells in each state; with image, the map as a picture too (a PNG
#' as its SVG export draws it: on white, the position and row medians, the color scale, the
#' tracks shown), for an agent to look at or a script to save.
#'
#' @param color_by score, se, replicates or input; differential for a run that compares
#' conditions. Optional; a string.
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param contrast With conditions compared: the contrast to color by, by name (such as "With
#' ligand vs Without ligand"); implies color_by differential. Optional; a string.
#' @param from The picture's first position (1 if not given). Optional; a whole number.
#' @param image Return the map as a picture (PNG) too. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param palette rdbu (blue loss, red gain) or puor (purple loss, orange gain). Optional; a
#' string.
#' @param rows The order of the substitutions: biochemical, hydrophobicity or alphabetical.
#' Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param scale The picture's size against the SVG export's, from 0.5 to 4 (2 if not given).
#' Optional; a number.
#' @param to The picture's last position (the target's last if not given). Optional; a whole
#' number.
#' @param zoom Zoom factor from the fitted map (above 1 zooms in). Optional; a number.
#' @param file Optional; save the picture to this path as a PNG file (and ask for it).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_render_map <- function(color_by = NULL, condition = NULL, contrast = NULL, from = NULL, image = NULL, palette = NULL, rows = NULL, run = NULL, scale = NULL, to = NULL, zoom = NULL, file = NULL, ms = ms_default()) {
  if (!is.null(file) && is.null(image)) image <- TRUE
  result <- ms_call("render_map", color_by = color_by, condition = condition, contrast = contrast, from = from, image = image, palette = palette, rows = rows, run = run, scale = scale, to = to, zoom = zoom, ms = ms)
  if (!is.null(file)) ms_save_image(result, file)
  result
}

#' A run's variants as a table
#'
#' A run's variants as a table, the columns of its scores export (scores.csv: hgvs_nt,
#' hgvs_splice, hgvs_pro, score, SE, ci95_lower, ci95_upper, df, SE_scale, replicates,
#' replicates_expected, status (scored, low confidence, filtered: the stage, not measured),
#' flags (why low confidence), tau2, I2, leave_one_out, variant_as_written, variant_class, each
#' replicate's score and SE); with contrast its differential scores (difference, SE, interval,
#' t or z, p, q), with protein a nucleotide run's scores at the protein level. Numbers as
#' numbers, null where the export has NA (df "Inf" when infinite). Only those at positions, of
#' kinds, in a saved selection or matching a query; sorted by a column; 100 rows from offset
#' unless limit says otherwise (0: every row).
#'
#' @param columns The columns to give (all if not given). Optional; a vector of strings
#' (Python: a list).
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param contrast With conditions compared: a contrast (its name, or its number from 1): its
#' differential scores. Optional; a string.
#' @param kinds Classes of variant: missense, nonsense, synonymous, and the others the table
#' has. Optional; a vector of strings (Python: a list).
#' @param limit The rows to give, from offset (100 if not given; 0 for all of them). Optional;
#' a whole number.
#' @param offset The rows to pass over first (0 if not given). Optional; a whole number.
#' @param positions Positions on the target (the variants' own numbering), each a number or a
#' stretch ("30-40"). Optional; a vector of strings (Python: a list).
#' @param protein A nucleotide run's scores at the protein level (protein_scores.csv).
#' Optional; TRUE or FALSE (Python: True or False).
#' @param query A query of the selection language (as select_variants takes it): the variants
#' it selects only. Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param selection A saved selection, by name: its variants only. Optional; a string.
#' @param sort A column to sort by ("score"; "-score" for the highest first); rows without a
#' value last. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_scores <- function(columns = NULL, condition = NULL, contrast = NULL, kinds = NULL, limit = NULL, offset = NULL, positions = NULL, protein = NULL, query = NULL, run = NULL, selection = NULL, sort = NULL, ms = ms_default()) {
  ms_call("scores", columns = .ms_array(columns), condition = condition, contrast = contrast, kinds = .ms_array(kinds), limit = limit, offset = offset, positions = .ms_array(positions), protein = protein, query = query, run = run, selection = selection, sort = sort, ms = ms)
}

#' A run's provenance
#'
#' A run's provenance as its export (provenance.json) holds it: the table and its mapping by
#' SHA-256, the design and its SHA-256, the parameters, the software, the output's SHA-256, the
#' QC findings with their thresholds and acknowledgements, and the workspace's history head.
#'
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_provenance <- function(condition = NULL, run = NULL, ms = ms_default()) {
  ms_call("provenance", condition = condition, run = run, ms = ms)
}

#' Compare two sets of scores
#'
#' Compares two sets of scores, as the Compare view does: each side a run's condition (its
#' combined scores) or one of its replicates, of one run or two (a rescoring, or a MaveDB
#' record's published scores against its counts scored again), or a MaveDB score set or a
#' predictor kept beside the workspace (a score set named by its URN is fetched and kept first,
#' without opening it; a predictor is AlphaMissense or a predictor's file added with
#' add_track). Returns the compatibility report first (targets and coordinates, the level, the
#' variants matched and those on one side only, the directions and scales, whether the two are
#' independent; each item ok, qualified or blocked), then the agreement of the variants
#' compared: Pearson's r and Spearman's rho, Lin's concordance and Bland–Altman's bias and
#' limits of agreement (the last two only on one scale), each with its 95\% interval; for two
#' independent sides on one scale, the variants that differ beyond their uncertainty (each
#' difference's z from both SEs, q by Benjamini–Hochberg) and the disagreement by position; a
#' predictor by rank (Spearman's rho) and by its classes (the measured scores in each class,
#' and the AUC of telling its benign from its pathogenic substitutions, with DeLong's
#' interval). The scale: as scored, stated to be one, or each side rescaled by its own anchors
#' (nonsense median 0 and wild type 1, or synonymous median 0 and nonsense median -1). Filters
#' leave out variants of low confidence, large SE or few reads. Shows the Compare view; export
#' with what comparison writes the variants compared or (a .json path) the report and
#' statistics, comparison-positions the disagreement by position, comparison-map a map (SVG),
#' comparison-classes a predictor by class.
#'
#' @param a The first side, by name: "Run 1", "Run 1: Replicate 2", "Run 1: +Lon", "Published
#' scores", a score set or predictor kept beside the workspace ("AlphaMissense: P62993"), or a
#' MaveDB score set's URN (fetched and kept when it is not yet). The pair shown, or a default
#' (a run against the published scores, two replicates, two conditions, the last two runs), if
#' not given. Optional; a string.
#' @param b The second side, by name or URN. Optional; a string.
#' @param direction What a higher score of the MaveDB score set compared means (MaveDB records
#' none): higher-more, higher-less, unsigned, or not stated. Optional; a string.
#' @param low_confidence Leave out the variants of low confidence on either side (true); those
#' given replace the comparison's filters, none given keeps them. Optional; TRUE or FALSE
#' (Python: True or False).
#' @param max_se Leave out the variants whose SE on either side is above this. Optional; a
#' number.
#' @param min_reads Leave out the variants with fewer input reads than this on either side.
#' Optional; a number.
#' @param report Keep the comparison in the workspace's report (true): its sides, scale,
#' filters and statistics, in the history; the report says it. Optional; TRUE or FALSE (Python:
#' True or False).
#' @param scale The scale they are compared on: scored (as scored, the default), stated (stated
#' to be one scale), nonsense-wt (each rescaled so its nonsense median is 0 and its wild type
#' 1) or synonymous-nonsense (its synonymous median 0 and nonsense median -1). Kept for the
#' comparisons that follow. Optional; a string.
#' @param show The tab shown: agreement (the scatter plot and statistics), maps (the two maps
#' and their difference), disagreement (the discordant variants and the positions) or classes
#' (a predictor's classes). Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_compare <- function(a = NULL, b = NULL, direction = NULL, low_confidence = NULL, max_se = NULL, min_reads = NULL, report = NULL, scale = NULL, show = NULL, ms = ms_default()) {
  ms_call("compare", a = a, b = b, direction = direction, low_confidence = low_confidence, max_se = max_se, min_reads = min_reads, report = report, scale = scale, show = show, ms = ms)
}

#' Check a run's robustness to analysis choices
#'
#' Checks a run's robustness to other reasonable analysis choices, as the Score view's
#' Robustness pane does: the run scored again with each alternative alone (pseudocount;
#' normalization; the model of uncertainty, DiMSum's error model or a regression's; the
#' combination of replicates; the minimum input count, replicates and time points; each
#' replicate left out), then seeded combinations of them. For each variant (and each difference
#' between conditions) its class (lower than, like or higher than the wild type, q < 0.05),
#' effect, rank, SE and inclusion in every analysis, and its verdict: robust, fragile (a choice
#' moves its effect beyond its 95\% interval and changes its class, the choice named), depends
#' on its uncertainty, borderline, its effect's size depends on a choice, or not always scored;
#' each alternative's effect; the least tolerant positions. Export with what robustness (the
#' variants, CSV; or its record, a .json path) or robustness-positions.
#'
#' @param max How many analyses in all (48 by default): the declared, each alternative alone,
#' then seeded combinations. Optional; a whole number.
#' @param report Keep the check in the workspace's report (true): the choices varied and what
#' each target's verdicts were, in the history; the report says it. Optional; TRUE or FALSE
#' (Python: True or False).
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_check_robustness <- function(max = NULL, report = NULL, run = NULL, ms = ms_default()) {
  ms_call("check_robustness", max = max, report = report, run = run, ms = ms)
}

#' The tracks beside the map
#'
#' The sequence tracks beside a run's map, in order: the run's own (reference, coverage,
#' position effect, uncertainty) and the workspace's annotations' (UniProt features,
#' conservation, AlphaMissense, ClinVar, gnomAD, MaveDB's annotations, an alignment, a
#' predictor, a custom track), each with its source (service, release, retrieval date), whether
#' it is shown, its filter and the filters it offers, and what it holds; the annotations that
#' could not be read; and what can be added.
#'
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_list_tracks <- function(condition = NULL, run = NULL, ms = ms_default()) {
  ms_call("list_tracks", condition = condition, run = run, ms = ms)
}

#' Add a track beside the map
#'
#' Adds an annotation's tracks beside the map. From public data, through MaveScape's list of
#' services (docs/NETWORK.md; from the cache only with --offline; only an accession, gene
#' symbol or URN is sent): provider uniprot-features, pdbe-conservation, alphamissense,
#' clinvar, gnomad or mavedb-annotations, for the run's target; or mavedb-scores with a urn, a
#' MaveDB score set kept beside the workspace without opening it (its record and published
#' scores; compared in Compare, its scores a track). Or from a file, given as name and text: an
#' alignment (A3M, FASTA, Stockholm, Clustal), a predictor's table (AlphaMissense, EVE, ESM1b,
#' or variants with scores) or a custom track (GFF3, or a table with position, or start and
#' end). The annotation is kept with the workspace (and its archive); in the history.
#'
#' @param direction mavedb-scores: what a higher score means (MaveDB records none):
#' higher-more, higher-less or unsigned. Optional; a string.
#' @param name A file's name (grb2-sh3.sto), with its text. Optional; a string.
#' @param provider The public source: uniprot-features, pdbe-conservation, alphamissense,
#' clinvar, gnomad, mavedb-annotations or mavedb-scores (with urn). Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param text A file's text: an alignment, a predictor's table or a custom track. Optional; a
#' string.
#' @param urn mavedb-scores: the score set's URN (urn:mavedb:00000054-a-1). Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_add_track <- function(direction = NULL, name = NULL, provider = NULL, run = NULL, text = NULL, urn = NULL, ms = ms_default()) {
  ms_call("add_track", direction = direction, name = name, provider = provider, run = run, text = text, urn = urn, ms = ms)
}

#' Show, move or filter a track
#'
#' Shows or hides a track, moves it, or filters it: features by kind (types), variants by class
#' (classes) or ClinVar's review status (stars, 0-4), gnomAD's frequency (min). The arrangement
#' is kept with the workspace; it is a view, not in the history.
#'
#' @param track The track by id or label (list_tracks). Required; a string.
#' @param filter {types: [...]}, {classes: [...], stars: n} or {min: x}, as the track offers
#' (list_tracks); {} removes its filter. Optional; a named list (Python: a dict).
#' @param position Its place among the tracks, from 1 (the top). Optional; a whole number.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param shown Show it (true) or hide it (false). Optional; TRUE or FALSE (Python: True or
#' False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_set_track <- function(track, filter = NULL, position = NULL, run = NULL, shown = NULL, ms = ms_default()) {
  ms_call("set_track", track = track, filter = filter, position = position, run = run, shown = shown, ms = ms)
}

#' Remove an annotation and its tracks
#'
#' Removes an annotation and its tracks (undoable, in the history).
#'
#' @param annotation The annotation by id or name (list_tracks). Required; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_remove_track <- function(annotation, ms = ms_default()) {
  ms_call("remove_track", annotation = annotation, ms = ms)
}

#' Open a structure
#'
#' Opens a structure in the Structure view: a PDB entry by its ID, or the AlphaFold DB model of
#' a UniProt accession ("target": the target's), fetched through the program (cached, then
#' available offline). A file of your own opens with open_files. Returns the structure in
#' words: its chains, the residues observed, its assemblies and what else it holds.
#'
#' @param alphafold A UniProt accession, such as P62993, for its AlphaFold DB model; "target"
#' for the target's. Optional; a string.
#' @param assembly A biological assembly by its id ("1"), or "asym" for the asymmetric unit;
#' the coordinates as deposited if not given. Optional; a string.
#' @param chain The chain to map the workspace's target on; the chain that holds the most of it
#' if not given. Optional; a string.
#' @param pdb A PDB ID, such as 2VWF. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_open_structure <- function(alphafold = NULL, assembly = NULL, chain = NULL, pdb = NULL, ms = ms_default()) {
  ms_call("open_structure", alphafold = alphafold, assembly = assembly, chain = chain, pdb = pdb, ms = ms)
}

#' Find structures of the target
#'
#' The PDB entries that cover the workspace's target (its UniProt accession), from PDBe's SIFTS
#' through the program: ranked by the target positions each covers, then resolution, each with
#' its method, chains and positions; and that its AlphaFold DB model covers it all.
#'
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_find_structures <- function(ms = ms_default()) {
  ms_call("find_structures", ms = ms)
}

#' Map the target onto the structure
#'
#' Maps the workspace's target onto the structure shown: the target aligned to each chain
#' (BLOSUM62, free end gaps), and on the chain chosen each position on a residue (identical or
#' another), in the structure's sequence but not observed, missing from it, or outside it;
#' ambiguous positions; the entry's own record of the UniProt residues compared. Returns the
#' mapping in words and by position.
#'
#' @param chain The chain to map the target on; the one that holds the most of it if not given.
#' Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_map_structure <- function(chain = NULL, ms = ms_default()) {
  ms_call("map_structure", chain = chain, ms = ms)
}

#' Draw, color and select on the structure
#'
#' Draws the structure shown another way (style, color, surface, assembly), colors its residues
#' by their target positions' scores (the run and condition the map shows, in the map's colors:
#' filtered and missing positions gray, never the wild type's color), and selects residues in
#' Proteoscope's selection language, draws them in a style of their own, labels them and
#' focuses on their neighborhood; or picks a residue as a click does (its substitutions
#' selected on the map, its position in the inspector). Returns the structure's state: what is
#' selected, labeled and focused on, the scores colored by, and the renderer (WebGPU, or the
#' Canvas renderer, which draws no surfaces).
#'
#' @param add pick: add the residue to the selection (or take it away), as a ⌘-click does.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param assembly A biological assembly by its id ("1"), or "asym" for the asymmetric unit;
#' clears the selection. Optional; a string.
#' @param calibration color fraction: a published calibration of the record whose scores the
#' run is, by title or number (from 1), instead of a threshold. Optional; a string.
#' @param color By the scores: median, mean, minimum, maximum, fraction (abnormal-like, with
#' threshold or calibration), count (substitutions scored), substitution (with substitution),
#' uncertainty (median SE), disagreement (the comparison Compare shows) or qc. Or the
#' structure's own: class (each position's structural class: buried, exposed, interface,
#' disordered), chain, entity, rainbow, secondary, moltype, element, residue, hydrophobicity,
#' nucleotide, bfactor, plddt (a predicted model) or uniform. Optional; a string.
#' @param fit Fit the whole structure in the view. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param focus Focus on the selected residues and their neighbors within 5 Å, side chains
#' drawn (false: the whole structure again). Optional; TRUE or FALSE (Python: True or False).
#' @param label Label the selected residues (false: remove their labels). Optional; TRUE or
#' FALSE (Python: True or False).
#' @param pick A residue picked as a click picks it: "A 183" (chain and number, with an
#' insertion code if any); its position's substitutions selected on the map, the position in
#' the inspector. Optional; a string.
#' @param select Residues to select: "resn CYS", "chain A and resi 40-80", "within 5 of
#' ligand", "helix and chain B", "pos 30-40" (target positions, on the chain mapped), "uniprot
#' 188-198" (the reference's); empty to clear the selection. Optional; a string.
#' @param show How the selected residues are drawn: sticks, ball-stick, spacefill, hide or none
#' (as the rest). Optional; a string.
#' @param side color fraction: below or above the threshold is abnormal-like (the readout's
#' loss side if not given). Optional; a string.
#' @param style cartoon, ball-stick, sticks, spacefill or trace. Optional; a string.
#' @param substitution color substitution: the amino acid each residue's substitution to is
#' shown (A or Ala; * or Ter for a stop). Optional; a string.
#' @param surface off, ses (molecular), sas (solvent-accessible), vdw or gaussian; WebGPU only.
#' Optional; a string.
#' @param threshold color fraction: the score beyond which a substitution is abnormal-like
#' (research use). Optional; a number.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_set_structure <- function(add = NULL, assembly = NULL, calibration = NULL, color = NULL, fit = NULL, focus = NULL, label = NULL, pick = NULL, select = NULL, show = NULL, side = NULL, style = NULL, substitution = NULL, surface = NULL, threshold = NULL, ms = ms_default()) {
  ms_call("set_structure", add = add, assembly = assembly, calibration = calibration, color = color, fit = fit, focus = focus, label = label, pick = pick, select = select, show = show, side = side, style = style, substitution = substitution, surface = surface, threshold = threshold, ms = ms)
}

#' The Structure view as a picture
#'
#' The Structure view as a picture (a PNG), as a figure panel of it is drawn: the structure as
#' shown, its coloring's legend below (legend: false, the view alone), with what it shows in
#' words.
#'
#' @param legend Draw the legend below the view (true if not given). Optional; TRUE or FALSE
#' (Python: True or False).
#' @param light On white, whatever the window's theme. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param scale The picture's size against the view's, from 0.5 to 4 (2 if not given).
#' Optional; a number.
#' @param file Optional; save the picture to this path as a PNG file (and ask for it).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_render_structure <- function(legend = NULL, light = NULL, scale = NULL, file = NULL, ms = ms_default()) {
  result <- ms_call("render_structure", legend = legend, light = light, scale = scale, ms = ms)
  if (!is.null(file)) ms_save_image(result, file)
  result
}

#' The structure as evidence
#'
#' What the structure shown says of the target's positions: each one's structural class
#' (buried, exposed, interface with the partners chosen, or a predicted model's disordered
#' region), from DSSP's secondary structure, the solvent accessibility (DSSP's radii),
#' StructureMap's exposure and the partners within 4 Å; the median scores of each class against
#' the rest (Mann–Whitney, BH-adjusted); and whether the least tolerant positions lie closer
#' together than positions of the same burial (pairs within 8 Å against seeded draws within
#' strata of relative accessibility). The same are tracks beside the map (list_tracks).
#'
#' @param fraction The share of positions called least tolerant for the cluster test (0.2 if
#' not given). Optional; a number.
#' @param partner The partner the interface is read with: "all" (every other chain, ligand and
#' ion but common additives, the default), or one by its id or label ("chain:B",
#' "ligand:A:1352:TLA"). Optional; a string.
#' @param seed The seed of the cluster test's draws (1 if not given). Optional; a whole number.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_structure_evidence <- function(fraction = NULL, partner = NULL, seed = NULL, ms = ms_default()) {
  ms_call("structure_evidence", fraction = fraction, partner = partner, seed = seed, ms = ms)
}

#' Save the structure view
#'
#' Saves the view of the structure shown with the workspace, under a name (one already used is
#' saved again): the structure's file kept in the library by its SHA-256 (and a model's aligned
