#' @param name The view's name. Required; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_save_structure_view <- function(name, ms = ms_default()) {
  ms_call("save_structure_view", name = name, ms = ms)
}

#' Open a saved structure view
#'
#' Opens a saved view as it was saved: its structure from the library (or fetched again by its
