#' Remove a saved structure view
#'
#' Removes a saved view, and its structure when no other view shows it (undoable, in the
#' history).
#'
#' @param name The saved view's name. Required; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_remove_structure_view <- function(name, ms = ms_default()) {
  ms_call("remove_structure_view", name = name, ms = ms)
}

#' The workspace's figures
#'
#' The workspace's figures: each one's name, page (millimeters, and the text size in points),
#' its panels lettered in reading order with what each shows, where it is (millimeters) and
#' anything wrong with it (text under 6 pt, a map too narrow for its positions, a run no longer
#' there), and the figure described in words.
#'
#' @param dpi The pictures' resolution, from 72 to 600 dots per inch (150 if not given).
#' Optional; a number.
#' @param figure A figure by name or id: only that one. Optional; a string.
#' @param image Each page as a picture too: a PNG as export_figure writes it. Optional; TRUE or
#' FALSE (Python: True or False).
#' @param file Optional; save the picture to this path as a PNG file (and ask for it).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_figures <- function(dpi = NULL, figure = NULL, image = NULL, file = NULL, ms = ms_default()) {
  if (!is.null(file) && is.null(image)) image <- TRUE
  result <- ms_call("figures", dpi = dpi, figure = figure, image = image, ms = ms)
  if (!is.null(file)) ms_save_image(result, file)
  result
}

#' Make a figure
#'
#' Makes a figure: an empty page at a journal's column width or a slide, shown in the Figures
#' view. Add panels with add_figure_panel.
#'
#' @param height_mm The page's height in millimeters, instead of the size's. Optional; a
#' number.
#' @param name Its name ("Figure 2"); Figure n if not given. Optional; a string.
#' @param size single (85 mm wide), onehalf (114 mm), double (174 mm, the default) or slide
#' (16:9). Optional; a string.
#' @param text The text size in points at the printed size (7, or 14 on a slide). Optional; a
#' number.
#' @param width_mm The page's width in millimeters, instead of the size's. Optional; a number.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_create_figure <- function(height_mm = NULL, name = NULL, size = NULL, text = NULL, width_mm = NULL, ms = ms_default()) {
  ms_call("create_figure", height_mm = height_mm, name = name, size = size, text = text, width_mm = width_mm, ms = ms)
}

#' Add a panel to a figure
#'
#' Adds a panel to a figure (or to a new one), drawn as its view draws it: a run's
#' variant-effect map (a condition or a difference between conditions, colored as render_map
#' colors it, a range of positions, tracks below it, its color bar and the key to its states);
#' a QC finding's charts (of a run, or of the counts); a run's scores by class, filter flow or
#' a contrast's volcano; a comparison (as compare takes its sides: agreement, Bland–Altman,
#' disagreement by position, a predictor's classes, or a map of either side or of the
#' difference); a variant's evidence (its score and each replicate's with their intervals, its
#' time course, or its distribution over the bins); a saved structure view (its figure panel,
#' drawn at 4x on white and kept with the figure); or text. Placed below the panels already
#' there unless placed; shown in the Figures view. Returns the panel's id and letter, and what
#' it shows.
#'
#' @param a compare: the first side, as compare takes it; the pair compared last if not given.
#' Optional; a string.
#' @param b compare: the second side. Optional; a string.
#' @param color_by score (the default), se, replicates or input. Optional; a string.
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param contrast With conditions compared: the difference to draw, by name (such as "With
#' ligand vs Without ligand"). Optional; a string.
#' @param figure The figure, by name or id; a new figure if not given. Optional; a string.
#' @param finding qc: the finding, by id (qc_findings lists them) or title. Optional; a string.
#' @param from The first position shown (the target's numbering). Optional; a whole number.
#' @param height_mm Its height. Optional; a number.
#' @param kind map (the default), qc, scores, compare, variant, structure or text. Optional; a
#' string.
#' @param pair qc, replicate agreement: the pair of replicates drawn, from 1. Optional; a whole
#' number.
#' @param palette rdbu or puor. Optional; a string.
#' @param plot What a scores panel shows (distribution, flow, volcano), a compare panel
#' (agreement, bland-altman, positions, classes, map-first, map-second, map-difference) or a
#' variant panel (evidence, time-course, bins). Optional; a string.
#' @param rows The order of the substitutions: biochemical, hydrophobicity or alphabetical.
#' Optional; a string.
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param scale compare: the scale, as compare takes it. Optional; a string.
#' @param subject qc: the run whose QC (by name), or counts; the latest run if not given.
#' Optional; a string.
#' @param text text: the panel's text. Optional; a string.
#' @param to The last position shown. Optional; a whole number.
#' @param tracks The tracks below the map, by id (list_tracks gives them); "shown" alone for
#' those shown beside the map; none if not given. Optional; a vector of strings (Python: a
#' list).
#' @param variant variant: its MAVE-HGVS name, such as p.Trp36Ala. Optional; a string.
#' @param view structure: the saved view, by name; the last saved if not given. Optional; a
#' string.
#' @param width_mm Its width (the page's, less its margins, if not given). Optional; a number.
#' @param x_mm Where the panel's left edge is, in millimeters from the page's. Optional; a
#' number.
#' @param y_mm Where its top is. Optional; a number.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_add_figure_panel <- function(a = NULL, b = NULL, color_by = NULL, condition = NULL, contrast = NULL, figure = NULL, finding = NULL, from = NULL, height_mm = NULL, kind = NULL, pair = NULL, palette = NULL, plot = NULL, rows = NULL, run = NULL, scale = NULL, subject = NULL, text = NULL, to = NULL, tracks = NULL, variant = NULL, view = NULL, width_mm = NULL, x_mm = NULL, y_mm = NULL, ms = ms_default()) {
  ms_call("add_figure_panel", a = a, b = b, color_by = color_by, condition = condition, contrast = contrast, figure = figure, finding = finding, from = from, height_mm = height_mm, kind = kind, pair = pair, palette = palette, plot = plot, rows = rows, run = run, scale = scale, subject = subject, text = text, to = to, tracks = .ms_array(tracks), variant = variant, view = view, width_mm = width_mm, x_mm = x_mm, y_mm = y_mm, ms = ms)
}

#' Change or delete a figure
#'
#' Changes a figure: its name, page size, text size and lettering, and its panels (moved,
#' resized, their options changed, removed), each change undoable. Returns the figure as
#' figures does.
#'
#' @param figure The figure, by name or id. Required; a string.
#' @param delete Delete the figure. Optional; TRUE or FALSE (Python: True or False).
#' @param height_mm Optional; a number.
#' @param letters Letter the panels A, B, C… in reading order. Optional; TRUE or FALSE (Python:
#' True or False).
#' @param name A new name. Optional; a string.
#' @param panels Changes to panels: each { panel (its id or letter), and any of x_mm, y_mm,
#' width_mm, height_mm; a map's from, to, condition, contrast, color_by, rows, palette, tracks,
#' medians, legend; a plot's plot and pair; any panel's title and letter; a text's text, size,
#' bold, align; or remove: true }. Optional; a vector of strings (Python: a list).
#' @param size single, onehalf, double or slide: the page's size (panels kept on it). Optional;
#' a string.
#' @param text The text size in points. Optional; a number.
#' @param width_mm Optional; a number.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_set_figure <- function(figure, delete = NULL, height_mm = NULL, letters = NULL, name = NULL, panels = NULL, size = NULL, text = NULL, width_mm = NULL, ms = ms_default()) {
  ms_call("set_figure", figure = figure, delete = delete, height_mm = height_mm, letters = letters, name = name, panels = .ms_array(panels), size = size, text = text, width_mm = width_mm, ms = ms)
}

#' Export a figure
#'
#' Writes a figure: SVG (vector, its text as text and its description in <desc>), PDF (vector,
#' one page at its printed size, text in Helvetica) or PNG at a resolution of its printed size
#' (300 dpi if not given, its resolution recorded in the file), each carrying its manifest
#' (what each panel shows and was drawn from: each run by its output's SHA-256, the QC
#' thresholds, the sides of a comparison, the tracks' files, a structure view's image; a digest
#' of each panel's drawing; MaveScape's version and commit; a fingerprint), or the manifest
#' alone (json). The same figure is the same bytes (with a fixed time, as mavescape run fixes
#' it). Needs the token.
#'
#' @param figure The figure, by name or id. Required; a string.
#' @param path The absolute path of the file to write. Required; a string.
#' @param dpi png: dots per inch of the printed size. Optional; a number.
#' @param format svg, pdf, png or json (the manifest); from the path's extension if not given.
#' Optional; a string.
#' @param overwrite Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_export_figure <- function(figure, path, dpi = NULL, format = NULL, overwrite = NULL, ms = ms_default()) {
  ms_call("export_figure", figure = figure, path = path, dpi = dpi, format = format, overwrite = overwrite, ms = ms)
}

#' Check an exported figure
#'
#' Reads a figure MaveScape exported (SVG, PDF, PNG, or its manifest as JSON): what it shows
#' and where it came from (the workspace, MaveScape's version, when), whether its manifest is
#' as it was written (its fingerprint), and panel by panel what changed in the workspace open
#' since (a run not here, a table scored again since, the QC thresholds or an acknowledgement
#' changed, an annotation's file changed, a structure view saved again). With rebuild, adds the
#' figure to the workspace, its panels drawn again from their inputs and each drawing compared
#' with the one the file records. Needs the token.
#'
#' @param paths The figure's file: one absolute path. Required; a vector of strings (Python: a
#' list).
#' @param rebuild Rebuild the figure in the workspace and say, panel by panel, whether it is
#' drawn the same. Optional; TRUE or FALSE (Python: True or False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_check_figure <- function(paths, rebuild = NULL, ms = ms_default()) {
  ms_call("check_figure", paths = .ms_array(paths), rebuild = rebuild, ms = ms)
}

#' Keep or delete a checkpoint
#'
#' Keeps a checkpoint: the analysis as it stands (the targets, design, runs, QC thresholds and
#' acknowledgements, selections, annotations, structure views, figures and what the report
#' keeps), named, with the history's hash at that moment, in the workspace and its archive; or
#' deletes one. Lists the checkpoints kept. Compare with diff.
#'
#' @param name The checkpoint's name ("Before the rescoring"): keeps one of the analysis as it
#' stands. Optional; a string.
#' @param remove A checkpoint, by name or id, to delete. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_checkpoint <- function(name = NULL, remove = NULL, ms = ms_default()) {
  ms_call("checkpoint", name = name, remove = remove, ms = ms)
}

#' What changed
#'
#' What changed between two states of the analysis, in words: from a checkpoint (the latest if
#' not given) to now or another checkpoint, or between two workspace archives (paths, the
#' earlier first). The tables, targets, design, runs scored and removed, QC thresholds and
#' acknowledgements, selections, annotations, structure views, figures, the report's analyses
#' and MaveDB details; and for each table's latest run, how its analysis changed (parameters,
#' filters, design) and what that did: for each condition, the variants whose effect moved
#' beyond their earlier 95\% interval, changed class (lower than, like or higher than the wild
#' type, q < 0.05) or were newly filtered or scored, the most moved by name, and the QC
#' findings whose verdict changed. Shows the changes in the Report view, with a map of the
#' change.
#'
#' @param from The checkpoint compared from, by name or id; the latest if not given. Optional;
#' a string.
#' @param paths Two workspace archives (.msz), absolute paths, the earlier first: compared
#' instead of checkpoints. Optional; a vector of strings (Python: a list).
#' @param show Show the changes in the Report view (the default); false leaves the view shown.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param to now (the default), or another checkpoint by name or id. Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_diff <- function(from = NULL, paths = NULL, show = NULL, to = NULL, ms = ms_default()) {
  ms_call("diff", from = from, paths = .ms_array(paths), show = show, to = to, ms = ms)
}

#' Certify the workspace
#'
#' Writes a reproducibility certificate of the workspace (.msz): the workspace archive with
#' every number it reports computed again from its files (each run's scores, SEs and classes
#' and its output's SHA-256; its QC findings and the SHA-256 of its whole QC; the comparisons
#' and robustness checks kept in the report; each figure panel's drawing by its SHA-256; the
#' report), the files by their SHA-256, the history's head, the checkpoints, what is not
#' computed again, and a fingerprint (the SHA-256 of what was certified, to quote with the
#' analysis). mavescape verify (or verify_certificate) computes every number again and compares
#' them bit for bit. Needs the token.
#'
#' @param path The absolute path of the certificate to write (.msz). Required; a string.
#' @param overwrite Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param tables Include the count tables (the default); false names each by its SHA-256 only,
#' for data that cannot be shared (verifying then needs them beside it). Optional; TRUE or
#' FALSE (Python: True or False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_certify <- function(path, overwrite = NULL, tables = NULL, ms = ms_default()) {
  ms_call("certify", path = path, overwrite = overwrite, tables = tables, ms = ms)
}

#' Write the review report
#'
#' Writes the review report of the workspace (.html): one self-contained file a reviewer opens
#' in any browser, without MaveScape (the experiment and design, the inputs with their SHA-256,
#' each run's parameters, classes and maps, the QC findings with their plots, the comparisons
#' and robustness checks kept in the report, the selections, structure views and figures, the
#' methods and the decision log), every number traced to where it comes from with its key and
#' exact value: the numbers of the certificate certify writes, whose fingerprint it names. It
#' loads nothing. Needs the token.
#'
#' @param path The absolute path of the report to write (.html). Required; a string.
#' @param overwrite Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param tables The report of the certificate with the count tables (the default); false, of
#' the one naming them by their SHA-256 only. Optional; TRUE or FALSE (Python: True or False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_review_report <- function(path, overwrite = NULL, tables = NULL, ms = ms_default()) {
  ms_call("review_report", path = path, overwrite = overwrite, tables = tables, ms = ms)
}

#' Verify a certificate
#'
#' Verifies a reproducibility certificate: checks its fingerprint, the workspace and every file
#' against their SHA-256 and the history's chain, computes every number again from the files
#' with this MaveScape's code and compares them bit for bit. Verdict verified, differs (each
#' difference listed) or incomplete (a file it names is missing: give it in paths; the
#' library's are found by their SHA-256). Shows the result in the Report view. Needs the token.
#'
#' @param paths Absolute paths: the certificate (.msz), and after it the files it names but
#' does not hold (each, or a folder of them), found by their SHA-256. Required; a vector of
#' strings (Python: a list).
#' @param library Look for the files it names in this MaveScape's library too (the default);
#' false uses only the certificate's and those given, as someone without this library would.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param review Also return the review report of the certificate verified (its HTML, as
#' review), the same file its maker writes. Optional; TRUE or FALSE (Python: True or False).
#' @param show Show the result in the Report view (the default); false leaves the view shown.
#' Optional; TRUE or FALSE (Python: True or False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_verify_certificate <- function(paths, library = NULL, review = NULL, show = NULL, ms = ms_default()) {
  ms_call("verify_certificate", paths = .ms_array(paths), library = library, review = review, show = show, ms = ms)
}

#' The report and its methods
#'
#' The workspace's report, shown in the Report view: its methods written from the record (each
#' run's data, design, scoring with a table of its parameters, and QC; the comparisons and
#' robustness checks kept in it; selections, annotations, structures, figures; every input's
#' SHA-256; the software; the decision log; the limitations; the research-use statement), with
#' numbered references: each section, the Markdown and the BibTeX, and the analyses kept in it.
#' Written again on every change: the same workspace gives the same text.
#'
#' @param remove An analysis kept in the report, by id or by its words ("the comparison of Run
#' 1 and Run 2"), taken out first. Optional; a string.
#' @param show Show the Report view (the default); false leaves the view shown. Optional; TRUE
#' or FALSE (Python: True or False).
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_report <- function(remove = NULL, show = NULL, ms = ms_default()) {
  ms_call("report", remove = remove, show = show, ms = ms)
}

#' Open the structure in Proteoscope
#'
#' Hands the structure shown to a Proteoscope running on this computer (found on its ports,
#' 8765-8814, or those --proteoscope names), in what it accepts: for a PDB entry or AlphaFold
#' DB model and a Proteoscope MaveScape was tested with (0.10), the link that opens it there
#' with the scores as its custom residue data, the residues drawn, hidden, selected, labeled
#' and focused on, and the camera (open the link in a browser); for another version, a link to
#' the structure alone; for a file of the person's, the session to open there as a file (export
#' proteoscope-session writes it). Refused, saying why, when Proteoscope is not running.
#'
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_proteoscope_link <- function(ms = ms_default()) {
  ms_call("proteoscope_link", ms = ms)
}

#' Export a file
#'
#' Writes a file: a run's scores or counts (MaveDB columns), differential scores, QC per sample
#' or per variant, provenance, the methods or their references, the map (SVG, with the tracks
#' shown), the tracks shown (CSV, position by position), the selection, the whole workspace as
#' an archive (.msz), the analysis package (.zip: counts, target, design, sample sheet,
#' parameters and what is missing), a run's MaveDB deposit (.zip: the scores, counts, column
#' descriptions, experiment and score set as MaveDB takes them), the comparison shown (its
#' matched variants, CSV; its report and statistics, JSON; its positions, maps or a predictor's
#' classes), a run's robustness to analysis choices, or the workspace's report (Markdown, its
#' references BibTeX). Needs the token.
#'
#' @param what scores, counts, differential, qc-samples, qc-variants, qc-findings, barcodes (a
#' table of barcodes), provenance, methods, references, map, tracks, selection, archive,
#' package, mavedb, comparison (the variants of the comparison shown, or its report and
#' statistics to a .json path), comparison-positions (its disagreement by position),
#' comparison-map (a map of it, SVG: map first, second or difference) or comparison-classes (a
#' predictor's classes: the measured scores in each), robustness (a run's robustness to
#' analysis choices: its variants, CSV, or its record, a .json path) or robustness-positions,
#' structure-mapping (the target on the structure shown, position by position, CSV),
#' structure-scores (the scores the structure is colored by, position by position, with each
#' residue's color, CSV), structure-evidence (what the structure says of each position:
#' secondary structure, accessibility, exposure, partner, class, with its median score, CSV)
#' structure-image (a figure panel of the view shown: PNG, its legend below it, what it shows
#' written into it), proteoscope-session (the view shown as a Proteoscope session,
#' .proteoscope.json: the structure, by its ID or embedded, its scores as residue data, the
#' residues drawn, selected and labeled, the camera; Proteoscope need not be running), report
#' (the workspace's report: its methods from the record, Markdown) or report-references (its
#' references, BibTeX). Required; a string.
#' @param path The absolute path of the file to write. Required; a string.
#' @param condition A condition by name or number (from 1), when the design has more than one;
#' the first if not given. Optional; a string.
#' @param include_structures archive: include the files of the structures the saved views show,
#' or name each by its ID and SHA-256 only (false). Not given: included when the library holds
#' every file, named by ID and SHA-256 when it does not (a workspace opened from an archive
#' that named them so), which the message says. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param include_tables archive: include the count tables (the default), or name each by its
#' SHA-256 only. Optional; TRUE or FALSE (Python: True or False).
#' @param legend structure-image: draw the legend below the image (the default). Optional; TRUE
#' or FALSE (Python: True or False).
#' @param light structure-image: on white whatever the page's theme, as a figure's structure
#' panel draws it. Optional; TRUE or FALSE (Python: True or False).
#' @param map comparison-map: first, second or difference (the default). Optional; a string.
#' @param overwrite Replace the file if it exists. Optional; TRUE or FALSE (Python: True or
#' False).
#' @param run A score run by name ("Run 2") or id; the latest run of the current design if not
#' given. Optional; a string.
#' @param scale structure-image: the image's size against the view's (4 if not given).
#' Optional; a number.
#' @param selection selection: a saved selection by name; the current selection if not given.
#' Optional; a string.
#' @param ms A connection from ms_connect() (default: the last one made).
#' @return A mavescape_result: the message and the data MaveScape answered with.
#' @export
ms_export <- function(what, path, condition = NULL, include_structures = NULL, include_tables = NULL, legend = NULL, light = NULL, map = NULL, overwrite = NULL, run = NULL, scale = NULL, selection = NULL, ms = ms_default()) {
  ms_call("export", what = what, path = path, condition = condition, include_structures = include_structures, include_tables = include_tables, legend = legend, light = light, map = map, overwrite = overwrite, run = run, scale = scale, selection = selection, ms = ms)
}
